    @if (isOpen()) {
      <div class="dialog-overlay" (click)="onCancel()">
        <div class="dialog-container" (click)="$event.stopPropagation()" tabindex="-1">
          <div class="dialog-header">
            <div class="dialog-icon"
                 [class.icon-danger]="data().type === 'danger'"
                 [class.icon-warning]="data().type === 'warning'"
                 [class.icon-info]="data().type === 'info' || !data().type">
              @switch (data().type) {
                @case ('danger') { ⚠️ }
                @case ('warning') { ⚠️ }
                @default { ❓ }
              }
            </div>
            <h3 class="dialog-title">{{ data().title }}</h3>
          </div>

          <div class="dialog-content">
            <p class="dialog-message">{{ data().message }}</p>
          </div>

          <div class="dialog-actions">
            <button 
              class="btn btn-secondary"
              (click)="onCancel()"
              type="button">
              {{ data().cancelText || 'Cancel' }}
            </button>
            <button 
              class="btn"
              [class.btn-danger]="data().type === 'danger'"
              [class.btn-warning]="data().type === 'warning'"
              [class.btn-primary]="data().type === 'info' || !data().type"
              (click)="onConfirm()"
              type="button">
              {{ data().confirmText || 'Confirm' }}
            </button>
          </div>
        </div>
      </div>
    }
  `,
  styles: [`...`],
  changeDetection: ChangeDetectionStrategy.OnPush
})

@Component({
  selector: 'app-toast',
  imports: [CommonModule],
  template: `
    <div class="toast-container">
      @for (toast of toasts(); track toast.id) {
        <div 
          class="toast"
          [class.toast-success]="toast.type === 'success'"
          [class.toast-error]="toast.type === 'error'"
          [class.toast-warning]="toast.type === 'warning'"
          [class.toast-info]="toast.type === 'info'">

          <div class="toast-icon">
            @switch (toast.type) {
              @case ('success') { ✓ }
              @case ('error') { ✕ }
              @case ('warning') { ⚠ }
              @case ('info') { ℹ }
            }
          </div>

          <div class="toast-content">
            <p class="toast-message">{{ toast.message }}</p>
            <small class="toast-time">{{ getTimeAgo(toast.createdAt) }}</small>
          </div>

          <button 
            class="toast-close"
            (click)="dismissToast(toast.id)"
            type="button"
            aria-label="Close notification">
            ×
          </button>
        </div>
      }
    </div>
  `,
  styles: [`...`],
  changeDetection: ChangeDetectionStrategy.OnPush
})

